export function firstUniqueCharacter(text) {
    const m = new Map();
    for (const c of text.toLowerCase())
        m.set(c, (m.get(c) || 0) + 1);
    for (let i = 0; i < text.length; i++)
        if (m.get(text[i].toLowerCase()) === 1)
            return text[i];
    return '';
}
